 static string ChoiceHint(string label,int index,object value,string fallback){
  var build=value as DlssBuild;if(build!=null)return build.Description;
  if(label.StartsWith("Posizione"))return new[]{"Mantiene la posizione già impostata. Se manca, usa il comportamento predefinito della build.","Il modello modifica l’immagine dopo che è stata ingrandita alla risoluzione di uscita. Elabora in genere più pixel e può richiedere più tempo GPU.","Il modello modifica l’immagine prima che venga ingrandita. Con un ingresso a risoluzione ridotta elabora meno pixel; resa e prestazioni vanno confrontate nel gioco. In DLAA il vantaggio può ridursi."}[index];
  if(label.StartsWith("Passaggi"))return new[]{"Esegue il modello una sola volta per immagine: il punto di partenza consigliato per contenere il carico GPU.","Esegue due passaggi del modello. Può trasformare maggiormente l’immagine, aumentando il costo GPU; non genera fotogrammi intermedi.","Esegue tre passaggi del modello. È l’opzione più impegnativa delle tre; può accentuare anche artefatti e alterazioni. Non equivale a MFG 3×."}[index];
  if(label=="Stile")return new[]{"Usa il profilo predefinito della build, senza scegliere un’impostazione artistica specifica.","Richiede il profilo Standard del modello. Il risultato dipende dal runtime e dal gioco; non è una regolazione di risoluzione.","Richiede il profilo Naturale del modello. Confronta la stessa scena: il nome non garantisce colori più fedeli o meno artefatti.","Richiede il profilo Cinematico del modello. Cambia la scelta artistica del modello, non il formato HDR o il numero di FPS."}[index];
  if(label=="Chi genera i fotogrammi?")return new[]{"Lascia invariata la configurazione FG attuale. Non annulla modifiche che hai già applicato.","Fa generare i fotogrammi a OptiScaler partendo dall’upscaler. Richiede i componenti NVIDIA FG / Streamline compatibili già installati.","Richiede il moltiplicatore alla FG nativa: devi attivare DLSS Frame Generation nel menu del gioco. Disabilita la generazione propria di OptiScaler per evitare due percorsi concorrenti.","Spegne FG e override gestiti da OptiScaler. La Frame Generation nativa si disattiva nel menu del gioco."}[index];
  if(label=="Moltiplicatore richiesto")return (index+2)+"×: per ogni fotogramma reale richiede "+(index+1)+" fotogramm"+(index==0?"a generato":"i generati")+". Non moltiplica la reattività. I valori superiori a 2× richiedono RTX 5000 oppure lo sblocco Ada sperimentale della build y4my4my4m con FG del gioco; restano subordinati al runtime.";
  if(label=="DLL di caricamento")return index==0?"Mantiene il loader OptiScaler riconosciuto, oppure cerca un nome libero. Scelta consigliata per ridurre il rischio di conflitti.":"Richiede di caricare OptiScaler come "+value+" accanto all’eseguibile. Funziona solo se il gioco carica questo nome. Non migliora la qualità dell’immagine; l’app non sovrascrive una DLL sconosciuta o appartenente ad altre mod.";
  if(label=="Scheda video")return index==0?"Se la GPU non viene rilevata, indica la serie effettivamente presente. La selezione non aggiunge funzionalità hardware.":index==1?"Serie RTX 4000 / Ada. Neural Rendering richiede un runtime di compatibilità; FG standard è 2×, MFG superiore è un percorso sperimentale separato.":"Serie RTX 5000 / Blackwell. Usa il runtime NR appropriato; il supporto MFG dipende anche dal gioco e dai componenti caricati.";
  return fallback;
 }
