 void Remember(){if(!rememberReady)return;try{var options=Options();options.Runtime="";Core.Pref.DlssChoices[game.Id]=options;rememberTimer.Stop();rememberTimer.Start();}catch{/* Incomplete numeric input is not a valid preference yet. */}}
 public static bool AppliedChoice(DlssScan s,string label,int index,object value){
  if(s==null||String.IsNullOrEmpty(s.Proxy))return false;
  if(label=="DLL di caricamento")return index>0&&String.Equals(s.Proxy,Convert.ToString(value),StringComparison.OrdinalIgnoreCase);
  if(label=="Stile")return Core.Get(s.Ini,"DlssNr","Style")== (index==0?"auto":(index-1).ToString());
  if(label.StartsWith("Passaggi"))return s.Build=="wilsjo2"&&Core.Get(s.Ini,"DlssNr","Passes")== (index+1).ToString();
  if(label.StartsWith("Posizione"))return s.Build=="wilsjo2"&&index>0&&Core.Get(s.Ini,"DlssNr","RunBeforeSR")== (index==2?"true":"false")&&new[]{"FinishedPicture","DeferredDLSS","ResidualAcrossRR"}.All(k=>Core.Get(s.Ini,"DlssNr",k)=="false")&&Core.Get(s.Ini,"DlssNr","ApplyModel")=="true";
  bool opti=Core.Get(s.Ini,"FrameGen","Enabled")=="true"&&Core.Get(s.Ini,"FrameGen","FGOutput")=="dlssg";
  bool stopped=Core.Get(s.Ini,"FrameGen","Enabled")=="false";int count;bool native=stopped&&Int32.TryParse(Core.Get(s.Ini,"DLSSG","OverrideInterpolationCount"),out count)&&count>0;
  if(label=="Chi genera i fotogrammi?")return index==1?opti:index==2?native:index==3&&stopped&&Core.Get(s.Ini,"DLSSG","OverrideInterpolationCount")=="auto";
  if(label=="Moltiplicatore richiesto")return (opti||native)&&Core.Get(s.Ini,"DLSSG",opti?"InterpolationCount":"OverrideInterpolationCount")== (index+1).ToString();
  return false;
 }
 DlssScan buildEvidenceScan;string buildEvidence="";
 bool VerifiedBuild(string id){if(!Object.ReferenceEquals(buildEvidenceScan,scan)){buildEvidenceScan=scan;buildEvidence="";try{if(scan.Managed&&scan.Proxy!=""){var m=DlssCore.ReadManifest(scan.Folder);var entry=m.Files.FirstOrDefault(f=>f.Name.Equals(scan.Proxy,StringComparison.OrdinalIgnoreCase));if(entry!=null&&entry.After==DlssCore.Hash(Path.Combine(scan.Folder,scan.Proxy)))buildEvidence=scan.Build;}}catch{}}return buildEvidence!=""&&buildEvidence==id;}
 static string InstalledVersion(string path){
  if(!File.Exists(path))return "Non installato";
  try{string v=System.Diagnostics.FileVersionInfo.GetVersionInfo(path).FileVersion;return String.IsNullOrWhiteSpace(v)?"Presente · versione non dichiarata":v.Replace(",", ".").Replace(" ","");}catch{return "Presente · versione non leggibile";}
 }
 void RefreshInstalled(){foreach(var refresh in choiceRefresh)refresh();if(installedLabel==null)return;try{
  var files=DlssLibraries.Scan(game);var lines=new System.Collections.Generic.List<string>();var paths=new System.Collections.Generic.List<string>();
  string[] labels={"DLSS · Super Resolution","DLSS · Ray Reconstruction","DLSS · Frame Generation"};
  for(int i=0;i<DlssLibraries.Names.Length;i++){string component=DlssLibraries.Names[i];var found=files.Where(f=>f.File.Equals(component,StringComparison.OrdinalIgnoreCase)).ToList();lines.Add(labels[i]+": "+(found.Count==0?"Non installato":String.Join(" / ",found.Select(f=>InstalledVersion(f.Path)).Distinct())+(found.Count>1?" · "+DlssLibraries.CopyLabel(found):"")));paths.AddRange(found.Select(f=>f.Relative+" · "+InstalledVersion(f.Path)));}
  string nr=Path.Combine(Path.GetDirectoryName(game.Exe),"nvngx_dlssnr.dll");lines.Add("Neural Rendering · modello: "+InstalledVersion(nr));if(File.Exists(nr))paths.Add(nr);
  lines.Add("File su disco · attivazione in gioco da verificare");installedLabel.Text=String.Join("\n",lines);installedLabel.ToolTip=new TextBlock{Text=String.Join("\n",paths)+"\n\n"+DlssLibraries.CopyExplanation(),TextWrapping=TextWrapping.Wrap,MaxWidth=680};
 }catch(Exception ex){installedLabel.ToolTip=null;installedLabel.Text="Lettura componenti non completata: "+ex.Message;}}
 static string Summary(DlssScan s){return s.Owner+(s.Blockers.Count>0?"\n"+String.Join("\n",s.Blockers):s.Managed?"\nInstallazione e configurazione gestite da HDLSS.":s.Autopilot||s.Proxy!=""?"\nPremi Installa OptiScaler per scaricare la build scelta e gestirla con HDLSS, con backup dei file precedenti. Non serve aprire altre app.":"\nPremi Installa OptiScaler: HDLSS scarica e installa direttamente la build selezionata.");}
 static int Percent(string ini,string key,int fallback){double v;return Double.TryParse(Core.Get(ini,"DlssNr",key),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out v)?Math.Max(0,Math.Min(100,(int)Math.Round(v*100))):fallback;}
 DlssBuild Selected(){return builds.SelectedItem as DlssBuild??DlssBuild.All[0];}
 DlssOptions Options(){return new DlssOptions{Build=Selected().Id,Enabled=enabled.IsChecked==true,Scale=(int)scale.Value,Style=styles.SelectedIndex-1,Placement=placement.SelectedIndex-1,Passes=passes.SelectedIndex+1,Strength=Core.Number(strength.Text,"Intensità",0,100),Runtime=runtime,Proxy=proxy.SelectedIndex==0?"auto":Convert.ToString(proxy.SelectedItem),Key=menuKey,FrameMode=new[]{"keep","opti","native","off"}[Math.Max(0,fgMode.SelectedIndex)],FrameMultiplier=fgCount.SelectedIndex+2,AdaMfg=adaMfg.IsChecked==true};}
 void ChooseRuntime(){var d=new Microsoft.Win32.OpenFileDialog{Filter="Runtime NR|nvngx_dlssnr.dll",Title="Scegli nvngx_dlssnr.dll"};if(d.ShowDialog(window)!=true)return;if(!DlssCore.Pe64(d.FileName))throw new Exception("Il runtime deve essere una DLL PE x64.");runtime=d.FileName;runtimeLabel.Text="Da installare (file selezionato): "+runtime+"\nSHA-256: "+DlssCore.Hash(runtime)+"\nCompatibilità GPU da verificare con la fonte dell’autore.";}
 void ChoosePackage(){using(var d=new System.Windows.Forms.FolderBrowserDialog()){d.Description="Cartella del pacchetto completo estratto, contenente OptiScaler.dll";if(d.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;if(!File.Exists(Path.Combine(d.SelectedPath,"OptiScaler.dll")))throw new Exception("Non trovo OptiScaler.dll nella cartella.");package=d.SelectedPath;packageBuild=Selected().Id;packageLabel.Text="Pacchetto locale per "+Selected().Name+":\n"+package;}}
 void UpdateRemove(){bool present=scan.Managed||scan.Autopilot||scan.Proxy!="";remove.IsEnabled=!busy&&present;remove.Content=present?"Disinstalla / ripristina":"OptiScaler non installato";HdrChoices.Help(remove,"Rimuove solo OptiScaler con un registro di ripristino riconosciuto. ReShade e MFG separato hanno una gestione distinta.");}
 void Busy(bool value){if(!value)RefreshInstalled();busy=value;controls.IsEnabled=!value;install.IsEnabled=save.IsEnabled=!value;UpdateRemove();}
 async Task<string> ResolveRuntime(DlssOptions options){
  scan=DlssCore.Inspect(game);int series=gpu.SelectedIndex==1?40:gpu.SelectedIndex==2?50:hardware.Series;
  string current=String.IsNullOrEmpty(runtime)?scan.Runtime:runtime,origin="";
  if(options.Enabled)hardware.Validate(series,current);
  options.Runtime=await Task.Run(()=>NrModels.EnsureRuntime(options.Enabled,current,series,message=>window.Dispatcher.Invoke(new Action(()=>status.Text=message)),out origin));
  return origin;
 }
 async void PrepareInstall(){try{Core.Closed(game);Busy(true);var options=Options();string origin=await ResolveRuntime(options);string folder=package,tag="pacchetto locale";var build=Selected();if(folder==""){DlssRelease release=null;folder=await Task.Run(()=>DlssCore.Fetch(build,message=>window.Dispatcher.Invoke(new Action(()=>status.Text=message)),out release));tag=release.Tag;}var plan=await Task.Run(()=>DlssCore.Prepare(game,options,folder,tag));if(origin!="")plan.Summary+="\n"+origin;Busy(false);Review(plan);}catch(Exception ex){Busy(false);Error(ex);}}
 async void SaveExisting(){try{Core.Closed(game);Busy(true);var options=Options();scan=DlssCore.Inspect(game);if(scan.Build!=""&&options.Build!=scan.Build)throw new Exception("Per cambiare build usa Installa OptiScaler. Applica impostazioni non sostituisce la build.");if(scan.Proxy=="")throw new Exception("Premi Installa OptiScaler: scaricherà automaticamente anche il modello necessario.");string origin=await ResolveRuntime(options);var plan=await Task.Run(()=>DlssCore.Prepare(game,options,null,"configurazione esistente"));if(origin!="")plan.Summary+="\n"+origin;Busy(false);Review(plan);}catch(Exception ex){Busy(false);Error(ex);}}

 void Review(DlssPlan plan){StackPanel body;var d=Dialogs.Create(window,"Controlla le modifiche",out body);d.Width=860;d.MaxHeight=SystemParameters.WorkArea.Height-40;var report=new TextBox{Text=plan.ToString(),IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Height=Math.Min(420,SystemParameters.WorkArea.Height-250),Margin=new Thickness(0,10,0,14)};body.Children.Add(report);var b=new Button{Content=plan.Uninstall?"Conferma ripristino":"Applica con backup",Style=window.TryFindResource("Primary") as Style};body.Children.Add(b);b.Click+=async(s,e)=>{b.IsEnabled=false;try{Busy(true);string backup=await Task.Run(()=>DlssCore.Apply(game,plan));Busy(false);d.Close();scan=DlssCore.Inspect(game);status.Text=Summary(scan);Busy(false);Dialogs.Notice(window,plan.Uninstall?"Ripristino completato":"DLSS configurato",plan.Uninstall?"File previsti ripristinati o messi da parte. Per verificare gli originali del gioco usa il launcher del gioco.":"File aggiornati e verificati. Avvia il gioco dal suo launcher e usa il menu OptiScaler per verificare Neural Rendering. La presenza dei file non certifica l’effetto attivo.",null).ShowDialog();status.Text+="\nCopia di recupero: "+backup;}catch(Exception ex){Busy(false);b.IsEnabled=true;Error(ex);}};d.Closing+=(s,e)=>{if(busy)e.Cancel=true;};d.ShowDialog();}
 void Libraries(){Libraries(null);}
 void Libraries(string component){
  StackPanel body;var d=Dialogs.Create(window,"DLL DLSS · versioni e ripristino",out body);d.Width=980;
  body.Children.Add(Text("Super Resolution, Ray Reconstruction e Frame Generation. Aggiorna solo le DLL già presenti nel gioco; il runtime NR rimane separato.",12));
  var list=new ComboBox{ItemsSource=DlssLibraries.Scan(game).Where(x=>component==null||x.File.Equals(component,StringComparison.OrdinalIgnoreCase)).ToList(),Margin=new Thickness(0,10,0,12)};body.Children.Add(list);if(list.Items.Count>0)list.SelectedIndex=0;if(component!=null){var item=list.Items.Cast<DlssLibrary>().FirstOrDefault(x=>x.File==component);if(item!=null)list.SelectedItem=item;}
  var info=Text("Scegli il componente e carica le ultime 10 versioni dal catalogo DLSS Swapper. Download dal suo archivio; origine della DLL visibile accanto alla versione. Firma NVIDIA e versione interna vengono verificate prima di applicare.",12);body.Children.Add(info);var versions=new ComboBox{Margin=new Thickness(0,8,0,12),FontSize=15};body.Children.Add(versions);list.SelectionChanged+=(s,e)=>versions.ItemsSource=null;var row=new WrapPanel();body.Children.Add(row);bool fetching=false;
  Action<string> prepare=file=>{var target=list.SelectedItem as DlssLibrary;if(target==null)throw new Exception("Nessuna DLL selezionata.");var plan=DlssLibraries.Prepare(game,target,file);d.Close();Review(plan);};
  var loadVersions=Button(row,"Carica ultime 10",async()=>{if(fetching)return;var target=list.SelectedItem as DlssLibrary;if(target==null){info.Text="Componente non presente nel gioco. Copiare una DLL non aggiunge il supporto a questa funzione: aggiorniamo soltanto componenti già installati.";return;}fetching=true;row.IsEnabled=list.IsEnabled=false;try{var tags=await Task.Run(()=>DllCatalog.Fetch(target.File));versions.ItemsSource=tags;if(tags.Count>0)versions.SelectedIndex=0;info.Text=tags.Count+" versioni dal catalogo DLSS Swapper. Puoi scegliere anche una versione precedente.";}catch(Exception ex){info.Text="Catalogo non disponibile: "+ex.Message+" Puoi importare una DLL da TechPowerUp.";}finally{fetching=false;row.IsEnabled=list.IsEnabled=true;}});
  Button(row,"Installa versione scelta",async()=>{if(fetching)return;var target=list.SelectedItem as DlssLibrary;var tag=versions.SelectedItem as DllDownload;if(target==null||tag==null){info.Text="Carica il catalogo e scegli una versione.";return;}fetching=true;row.IsEnabled=list.IsEnabled=versions.IsEnabled=false;try{string file=await Task.Run(()=>DllCatalog.Download(tag,msg=>d.Dispatcher.Invoke(new Action(()=>info.Text=msg))));fetching=false;prepare(file);}catch(Exception ex){info.Text=ex.Message;}finally{fetching=false;row.IsEnabled=list.IsEnabled=versions.IsEnabled=true;}},true);
  Button(row,"Ultima da NVIDIA",async()=>{if(fetching)return;var target=list.SelectedItem as DlssLibrary;if(target==null)return;fetching=true;row.IsEnabled=list.IsEnabled=versions.IsEnabled=false;try{string file=await Task.Run(()=>DlssLibraries.Latest(target.File,msg=>d.Dispatcher.Invoke(new Action(()=>info.Text=msg))));fetching=false;prepare(file);}catch(Exception ex){info.Text=ex.Message;}finally{fetching=false;row.IsEnabled=list.IsEnabled=versions.IsEnabled=true;}});
  Button(row,"TechPowerUp",()=>{var target=list.SelectedItem as DlssLibrary;if(target!=null)Open(DlssLibraries.Tpu(target.File));});
  Button(row,"Importa DLL…",()=>{var target=list.SelectedItem as DlssLibrary;if(target==null)return;var file=new Microsoft.Win32.OpenFileDialog{Filter="DLL del componente|"+target.File};if(file.ShowDialog(d)==true)prepare(file.FileName);});
  Button(row,"Ripristina solo questa DLL",()=>{var target=list.SelectedItem as DlssLibrary;if(target==null)return;var plan=DlssLibraries.Restore(game,target);d.Close();Review(plan);});
  body.Children.Add(Text("Il download non modifica il gioco. Dopo la verifica della firma NVIDIA vedrai versione e percorso esatti prima di confermare. Per TechPowerUp, scarica ed estrai il file dal sito, poi scegli Importa DLL. Un aggiornamento non abilita MFG su hardware non supportato.",11));
  d.ContentRendered+=(s,e)=>loadVersions.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));d.Closing+=(s,e)=>{if(fetching)e.Cancel=true;};d.ShowDialog();RefreshInstalled();
 }
 void ShowReport(string title,string report){StackPanel body;var d=Dialogs.Create(window,title,out body);d.Width=900;body.Children.Add(new TextBox{Text=report,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Height=480});d.ShowDialog();}
 static void Open(string path){System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(path){UseShellExecute=true});}
